#[derive(Debug, Clone, PartialEq)]
pub enum TileCollisionType {
    None,
    Solid,
    OneWayPlatform,
    Pitfall,        // Deadly - kills player
    Passage,        // Can fall through - leads to vertical areas
    Water,          // Swimming area
    SwimThrough,    // Can only pass through when swimming
}

#[derive(Debug, Clone, PartialEq)]
pub enum PlayerState {
    Walking,
    Jumping,
    Falling,
    Swimming,
}

// Sprite data for rendering
#[derive(Debug, Clone)]
pub struct RenderSprite {
    pub x: f32,
    pub y: f32,
    pub sprite_data: Vec<Vec<u8>>,
    pub flip_horizontal: bool,
    pub scale: f32, // Scale multiplier (1.0 = normal, 4.0 = giant)
}

#[derive(Debug, Clone, PartialEq)]
pub enum GameState {
    TitleScreen,
    Cutscene,
    Playing,
}

#[derive(Debug, Clone, PartialEq)]
pub enum CutsceneType {
    Intro,
    Interlude1,
    Interlude2,
    Interlude3,
    Interlude4,
    Ending,
}

#[derive(Debug, Clone)]
pub struct CutsceneScreen {
    pub image: [[u8; 64]; 64],
    pub text_lines: Vec<String>,
    pub sound_id: Option<u32>,
}

#[derive(Debug, Clone)]
pub struct Cutscene {
    pub cutscene_type: CutsceneType,
    pub screens: Vec<CutsceneScreen>,
    pub current_screen: usize,
    pub text_scroll_offset: f32,
    pub text_scroll_speed: f32,
    pub text_char_index: usize,  // Current character being displayed
    pub text_char_timer: f32,    // Timer for character reveal
    pub chars_per_frame: f32,    // Speed of typing (0.5 = 2 frames per char, 1.0 = 1 char per frame)
}

// Player sprite constants
const PLAYER_SPRITE_WIDTH: f32 = 24.0;
const PLAYER_SPRITE_HEIGHT: f32 = 24.0;
const PLAYER_SPRITE_HALF_WIDTH: f32 = PLAYER_SPRITE_WIDTH / 2.0;
const PLAYER_SPRITE_HALF_HEIGHT: f32 = PLAYER_SPRITE_HEIGHT / 2.0;
// Reduce bottom collision so feet touch ground (smaller = lower to ground)
const PLAYER_SPRITE_BOTTOM_OFFSET: f32 = PLAYER_SPRITE_HALF_HEIGHT - 1.0;

#[derive(Debug, Clone)]
pub struct Hexagnome {
    pub x: f32,
    pub y: f32,
    pub vx: f32,
    pub patrol_left: f32,
    pub patrol_right: f32,
    pub facing_right: bool,
    pub shoot_timer: f32,
    pub health: i32,
    pub active: bool,
}

#[derive(Debug, Clone)]
pub struct Projectile {
    pub x: f32,
    pub y: f32,
    pub vx: f32,
    pub vy: f32,
    pub active: bool,
    pub palette_cycle_timer: f32, // For energy palette cycling effect
}

#[derive(Debug, Clone)]
pub struct Hamberry {
    pub x: f32,
    pub y: f32,
    pub collected: bool,
    pub animation_timer: f32, // For bobbing/spinning animation
}

// Power Pellet - spawns from boxes when hit, rises up, then can be collected
#[derive(Clone)]
pub struct PowerPellet {
    pub x: f32,
    pub y: f32,
    pub collected: bool,
    pub rising: bool,          // True while pellet is rising from box
    pub rise_timer: f32,       // Timer for rising animation
    pub animation_timer: f32,  // For pulsing/glowing effect
}

// Pellet Box - hits from below spawn power pellets
#[derive(Clone)]
pub struct PelletBox {
    pub x: f32,
    pub y: f32,
    pub activated: bool,  // True if pellet has already been spawned
}

pub struct PlatformerCartridge {
    game_state: GameState,
    title_blink_timer: f32, // Timer for blinking "PRESS START"
    current_cutscene: Option<Cutscene>,
    current_level: u32,  // Track current level (0-4)
    previous_input: u8,  // Track previous frame's input for button press detection
    camera_x: f32,
    camera_y: f32,
    player_x: f32,
    player_y: f32,
    player_vx: f32,
    player_vy: f32,
    on_ground: bool,
    player_state: PlayerState,
    animation_frame: u32,
    animation_timer: f32,
    facing_right: bool, // true = facing right, false = facing left
    level_width: f32,
    level_height: f32,
    // Jump mechanics
    jump_button_held: bool, // Track if jump button is currently held
    jump_hold_time: f32, // How long jump has been held (in frames)
    jumping: bool, // True if currently in a jump
    // Lives and death
    lives: u32,
    is_dying: bool, // True when death animation is playing
    death_timer: f32, // Timer for death animation
    invulnerability_timer: f32, // Invulnerability period after taking damage
    // Combat
    is_punching: bool, // True when punch attack is active
    punch_timer: f32, // Timer for punch animation duration
    // Sound effects
    pending_sounds: Vec<u32>,
    // Large tile map - 200x15 tiles (3200x240 pixels with 16x16 tiles)
    tiles: [[u8; 200]; 15],
    // Enemies/NPCs
    hexagnomes: Vec<Hexagnome>,
    projectiles: Vec<Projectile>,
    // Collectibles
    hamberries: Vec<Hamberry>,
    hamberries_collected: u32,
    power_pellets: Vec<PowerPellet>,
    pellet_boxes: Vec<PelletBox>,
    pellets_collected: u32,
    // Background music
    music_enabled: bool,
    music_timer: f32,
    lead_pattern: u8, // 1 = LEVEL1_LEAD, 2 = LEVEL1_LEAD2
    lead_16th_counter: u32, // Counts 16th notes within current 48-note pattern
    lead_note_index: usize,
    lead_note_remaining: u32,
    lead2_lower_index: usize,
    lead2_lower_remaining: u32,
    lead2_upper_index: usize,
    lead2_upper_remaining: u32,
    bass_16th_index: usize, // Index into LEVEL1_BASS_FULL array (advances every 16th note)
    music_16th_counter: u32, // Counts 16th notes for kick drum timing
}

