    // Skip directly to gameplay (for testing/debugging)
    pub fn skip_to_gameplay(&mut self) {
        self.game_state = GameState::Playing;
        self.current_cutscene = None;
        self.lives = 99; // Give lots of lives for testing
        self.is_dying = false;
        self.death_timer = 0.0;
    }

    pub fn update(&mut self, input: u8) {
        // Handle title screen separately
        if self.game_state == GameState::TitleScreen {
            self.update_title_screen(input);
            return;
        }

        // Handle cutscene separately
        if self.game_state == GameState::Cutscene {
            self.update_cutscene(input);
            return;
        }

        // Simple player movement
        const PLAYER_SPEED: f32 = 4.0;
        const GRAVITY: f32 = 0.5;
        const JUMP_SPEED: f32 = -12.0;

        // Handle input
        let left = (input & 0x01) != 0;
        let right = (input & 0x02) != 0;
        let up = (input & 0x04) != 0; // Up arrow/W key
        let jump = (input & 0x10) != 0; // A button
        let attack = (input & 0x20) != 0; // B button for punch
        
        
        // Horizontal movement
        if left {
            self.player_vx = -PLAYER_SPEED;
            self.facing_right = false; // Face left when moving left
        } else if right {
            self.player_vx = PLAYER_SPEED;
            self.facing_right = true; // Face right when moving right
        } else {
            self.player_vx = 0.0;
        }
        
        // Variable jump height system
        let jump_input = jump || up;
        
        // Start new jump from ground
        if jump_input && self.on_ground {
            self.jumping = true;
            self.jump_button_held = true;
            self.jump_hold_time = 0.0;
            self.player_vy = JUMP_SPEED * 0.3; // Start with weak jump
            self.on_ground = false;
            // Don't play sound immediately - wait to see if it's short or long jump
        }
        
        // Continue adding power while holding jump and in air
        if jump_input && self.jump_button_held && self.jumping {
            self.jump_hold_time += 1.0;
            
            // Play long jump sound on frame 3 of holding
            if self.jump_hold_time == 3.0 {
                self.trigger_sound(0); // Long jump sound (ID 0)
            }
            
            // Add upward velocity for first 12 frames
            if self.jump_hold_time <= 12.0 {
                self.player_vy -= 0.6; // Add upward velocity each frame
            }
        }
        
        // Handle jump button release
        if !jump_input && self.jump_button_held {
            self.jump_button_held = false;
            
            // If released quickly (within 2 frames), play short jump sound
            if self.jumping && self.jump_hold_time <= 2.0 {
                self.trigger_sound(2); // Short jump sound (ID 2) 
            }
        }
        
        // Reset jumping state when landing
        if self.on_ground {
            self.jumping = false;
            self.jump_button_held = false;
            self.jump_hold_time = 0.0;
        }
        
        // Punch attack handling
        const PUNCH_DURATION: f32 = 15.0; // Punch lasts 15 frames (~0.25 seconds at 60fps)

        // Start punch if attack button pressed and not already punching
        if attack && !self.is_punching && self.punch_timer == 0.0 {
            self.is_punching = true;
            self.punch_timer = PUNCH_DURATION;
            self.pending_sounds.push(10); // Punch sound (will need to add this)
        }

        // Update punch timer
        if self.punch_timer > 0.0 {
            self.punch_timer -= 1.0;
            if self.punch_timer <= 0.0 {
                self.is_punching = false;
                self.punch_timer = 0.0;
            }
        }

        // Apply gravity
        self.player_vy += GRAVITY;

        // Update position with collision
        self.update_physics();
        
        // Update animation
        self.update_animation();
        
        // Update camera to follow player
        self.camera_x = (self.player_x - 160.0).max(0.0);
        let max_camera_x = self.level_width - 320.0;
        if self.camera_x > max_camera_x {
            self.camera_x = max_camera_x;
        }
        
        // Check for pitfall death
        if !self.is_dying && self.check_for_pitfall(self.player_x, self.player_y) {
            self.start_death_animation();
        }

        // Check if player fell below the level (fell through gaps)
        if !self.is_dying && self.player_y > 240.0 {
            self.start_death_animation();
        }

        // Handle death animation
        if self.is_dying {
            self.update_death_animation();
            return; // Don't process normal gameplay during death
        }
        
        // Check punch collisions with enemies
        self.check_punch_collisions();

        // Check Hamberry collection
        self.check_hamberry_collection();

        // Check power pellet collection
        self.check_power_pellet_collection();

        // Update power pellets (rising animation)
        self.update_power_pellets();

        // Update hexagnomes
        self.update_hexagnomes();

        // Update projectiles
        self.update_projectiles();

        // Check projectile collisions with player
        self.check_projectile_collisions();

        // Update invulnerability timer
        if self.invulnerability_timer > 0.0 {
            self.invulnerability_timer -= 1.0;
        }

        // Update background music
        self.update_music();
    }
    
    fn update_physics(&mut self) {
        // Try horizontal movement first
        let new_x = self.player_x + self.player_vx;
        if !self.check_tile_collision(new_x, self.player_y) {
            self.player_x = new_x;
        }
        
        // Keep player in bounds horizontally
        if self.player_x < PLAYER_SPRITE_HALF_WIDTH {
            self.player_x = PLAYER_SPRITE_HALF_WIDTH;
        }
        if self.player_x > self.level_width - PLAYER_SPRITE_HALF_WIDTH {
            self.player_x = self.level_width - PLAYER_SPRITE_HALF_WIDTH;
        }
        
        // Try vertical movement
        let new_y = self.player_y + self.player_vy;
        
        // Check for collision at new vertical position
        if !self.check_tile_collision(self.player_x, new_y) {
            // No collision, move freely
            self.player_y = new_y;
            
            // Check if we're still on ground by looking slightly below
            let ground_check_y = self.player_y + PLAYER_SPRITE_BOTTOM_OFFSET;
            self.on_ground = self.check_tile_collision(self.player_x, ground_check_y);
        } else {
            // Collision detected
            if self.player_vy > 0.0 {
                // Moving down - landing
                if !self.on_ground {
                    self.trigger_sound(1); // Landing sound (ID 1) - only if we weren't already on ground
                }
                self.player_vy = 0.0;
                self.on_ground = true;
            } else if self.player_vy < 0.0 {
                // Moving up - hit ceiling
                self.player_vy = 0.0;
                // Check if player hit a pellet box from below
                self.check_pellet_box_hit();
            }
        }

        // Don't use a fallback floor - let player fall through gaps and trigger death
        // (Death is handled by checking if player_y > 240.0)
    }
    
    fn check_tile_collision(&self, x: f32, y: f32) -> bool {
        // Check multiple points around the player sprite to prevent phasing through tiles
        // This includes corners, midpoints on each edge, and center points
        let check_points = [
            // Four corners (bottom extended by 1 pixel for feet)
            (x - PLAYER_SPRITE_HALF_WIDTH, y - PLAYER_SPRITE_HALF_HEIGHT), // Top-left
            (x + PLAYER_SPRITE_HALF_WIDTH, y - PLAYER_SPRITE_HALF_HEIGHT), // Top-right
            (x - PLAYER_SPRITE_HALF_WIDTH, y + PLAYER_SPRITE_BOTTOM_OFFSET), // Bottom-left
            (x + PLAYER_SPRITE_HALF_WIDTH, y + PLAYER_SPRITE_BOTTOM_OFFSET), // Bottom-right
            // Midpoints on edges (critical for platforms)
            (x, y - PLAYER_SPRITE_HALF_HEIGHT), // Top-center
            (x, y + PLAYER_SPRITE_BOTTOM_OFFSET), // Bottom-center
            (x - PLAYER_SPRITE_HALF_WIDTH, y), // Left-center
            (x + PLAYER_SPRITE_HALF_WIDTH, y), // Right-center
            // Additional bottom points for better platform collision
            (x - PLAYER_SPRITE_HALF_WIDTH / 2.0, y + PLAYER_SPRITE_BOTTOM_OFFSET), // Bottom-quarter-left
            (x + PLAYER_SPRITE_HALF_WIDTH / 2.0, y + PLAYER_SPRITE_BOTTOM_OFFSET), // Bottom-quarter-right
        ];

        for (point_x, point_y) in check_points.iter() {
            if *point_x < 0.0 || *point_y < 0.0 {
                continue;
            }

            let tile_x = (*point_x / 16.0) as usize;
            let tile_y = (*point_y / 16.0) as usize;

            if tile_x < 200 && tile_y < 15 {
                let tile_type = self.tiles[tile_y][tile_x];
                // Only solid blocks (1) and platforms (2) cause collision
                // Air (0), pitfalls (3), and passages (4) allow movement
                if tile_type == 1 || tile_type == 2 {
                    return true; // Collision detected
                }
            }
        }

        false // No collision
    }
    
    fn check_for_pitfall(&self, x: f32, y: f32) -> bool {
        // Check if player is standing on a pitfall
        let tile_x = (x / 16.0) as usize;
        let tile_y = (y / 16.0) as usize;

        if tile_x < 200 && tile_y < 15 {
            return self.tiles[tile_y][tile_x] == 3; // Pitfall tile
        }
        false
    }

    fn start_death_animation(&mut self) {
        self.is_dying = true;
        self.death_timer = 0.0;
        self.player_vy = -15.0; // Launch Hambert upward
        self.player_vx = 0.0; // Stop horizontal movement

        // Play death sound (sound ID 8 - we'll add this)
        self.pending_sounds.push(8);

        // Lose a life
        if self.lives > 0 {
            self.lives -= 1;
        }
    }

    fn update_death_animation(&mut self) {
        self.death_timer += 1.0;

        // Make Hambert fly upward and off screen
        self.player_vy += 0.8; // Gravity during death animation
        self.player_y += self.player_vy;

        // After 120 frames (2 seconds at 60fps), respawn or game over
        if self.death_timer > 120.0 {
            if self.lives > 0 {
                // Respawn at start
                self.player_x = 50.0;
                self.player_y = 100.0;  // Spawn higher, let physics settle
                self.player_vx = 0.0;
                self.player_vy = 0.0;
                self.camera_x = 0.0;
                self.camera_y = 0.0;
                self.is_dying = false;
                self.death_timer = 0.0;
            } else {
                // Game over - return to title screen
                self.game_state = GameState::TitleScreen;
                self.lives = 3; // Reset lives for next playthrough
                self.player_x = 50.0;
                self.player_y = 100.0;  // Spawn higher, let physics settle
                self.player_vx = 0.0;
                self.player_vy = 0.0;
                self.camera_x = 0.0;
                self.camera_y = 0.0;
                self.is_dying = false;
                self.death_timer = 0.0;
            }
        }
    }

    fn check_for_passage(&self, x: f32, y: f32) -> bool {
        // Check if player is in a passage
        let tile_x = (x / 16.0) as usize;
        let tile_y = (y / 16.0) as usize;
        
        if tile_x < 200 && tile_y < 15 {
            return self.tiles[tile_y][tile_x] == 4; // Passage tile
        }
        false
    }
    
    fn get_tile_collision_type(&self, tile_id: u8) -> TileCollisionType {
        match tile_id {
            0 => TileCollisionType::None,           // Air
            1 => TileCollisionType::Solid,          // Solid block
            2 => TileCollisionType::OneWayPlatform, // Platform
            3 => TileCollisionType::Pitfall,        // Pitfall (deadly)
            4 => TileCollisionType::Passage,        // Passage (leads down)
            5 => TileCollisionType::Water,          // Water
            6 => TileCollisionType::SwimThrough,    // Swim-through tunnel
            _ => TileCollisionType::None,           // Default to air
        }
    }
    
    fn update_animation(&mut self) {
        // Always increment timer to see if function is called
        self.animation_timer += 1.0;

        // Check if jumping or in air
        if !self.on_ground {
            // Use jump sprite when in air
            self.animation_frame = 3;
            return;
        }

        // Simple frame-count based animation for ground movement
        let is_walking = self.player_vx.abs() > 0.1 && self.on_ground;

        if is_walking {
            // 4-frame cycle: 0, 1, 0, 2 (idle, walk1, idle, walk2)
            // Change every 4 frames (about 0.067 seconds at 60 FPS)
            let frame_duration = 4.0;
            let cycle_frame = ((self.animation_timer / frame_duration) as u32) % 4;

            self.animation_frame = match cycle_frame {
                0 => 0, // idle
                1 => 1, // walk1
                2 => 0, // idle again
                3 => 2, // walk2
                _ => 0,
            };
        } else {
            // Standing still - use idle frame
            self.animation_frame = 0;
        }
    }
    
    pub fn get_animation_frame(&self) -> u32 {
        self.animation_frame
    }
    
    pub fn is_facing_right(&self) -> bool {
        self.facing_right
    }
    
    pub fn get_sprite_data(&self, frame: u32) -> &[[u8; 24]; 24] {
        match frame {
            0 => &HAMBERT_IDLE_SPRITE,
            1 => &HAMBERT_WALK1_SPRITE,
            2 => &HAMBERT_WALK2_SPRITE,
            3 => &HAMBERT_JUMP_SPRITE,
            _ => &HAMBERT_IDLE_SPRITE,
        }
    }
    
